create extension if not exists vector;
create type public.capture_state as enum ('received','normalised','content_acquired','understood','connected','routed','executing','completed','needs_content','awaiting_approval','retrying','failed','partially_completed');
create table public.owner_profiles(id uuid primary key references auth.users on delete cascade,display_name text not null,instagram_handle text not null default '@kdn_brain',location text,available_time text,budget jsonb not null default '{}',constraints text[],do_not_want text[],automation_paused boolean not null default false,created_at timestamptz not null default now());
create table public.goals(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.owner_profiles on delete cascade,title text not null,description text,status text not null default 'active',created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.owner_profiles on delete cascade,goal_id uuid references public.goals on delete set null,title text not null,description text,status text not null default 'active',created_at timestamptz not null default now());
create table public.raw_events(id uuid primary key default gen_random_uuid(),provider text not null,event_id text not null unique,message_id text,sender_id text,disposition text not null,payload jsonb not null,received_at timestamptz not null default now());
create table public.captures(id uuid primary key default gen_random_uuid(),owner_id uuid references public.owner_profiles on delete cascade,raw_event_id uuid references public.raw_events,state public.capture_state not null default 'received',source_kind text not null,source_url text,owner_note text,explicit_intent text,inferred_intent text,content_state text not null default 'NEEDS_CONTENT',coverage jsonb not null default '{}',interest_count int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.media_assets(id uuid primary key default gen_random_uuid(),capture_id uuid not null references public.captures on delete cascade,storage_path text,mime_type text,bytes bigint,duration_seconds numeric,source_url_expires_at timestamptz,sha256 text,provenance jsonb not null default '{}',created_at timestamptz not null default now());
create table public.observations(id uuid primary key default gen_random_uuid(),capture_id uuid not null references public.captures on delete cascade,media_asset_id uuid references public.media_assets on delete cascade,kind text not null,start_ms int,end_ms int,content text not null,confidence numeric,provenance jsonb not null default '{}');
create table public.knowledge_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.owner_profiles on delete cascade,capture_id uuid references public.captures on delete set null,title text not null,body text not null,kind text not null,evidence_quality text not null default 'unassessed',created_at timestamptz not null default now());
create table public.knowledge_chunks(id uuid primary key default gen_random_uuid(),knowledge_item_id uuid not null references public.knowledge_items on delete cascade,content text not null,embedding vector(1536),ts tsvector generated always as (to_tsvector('english',content)) stored);
create index knowledge_chunks_embedding on public.knowledge_chunks using hnsw(embedding vector_cosine_ops);create index knowledge_chunks_ts on public.knowledge_chunks using gin(ts);
create table public.entities(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.owner_profiles on delete cascade,name text not null,kind text not null,unique(owner_id,name,kind));
create table public.item_entities(item_id uuid not null references public.knowledge_items on delete cascade,entity_id uuid not null references public.entities on delete cascade,relationship text not null,evidence jsonb not null default '{}',primary key(item_id,entity_id,relationship));
create table public.actions(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.owner_profiles on delete cascade,capture_id uuid references public.captures,project_id uuid references public.projects,type text not null,intended_result text not null,inputs jsonb not null,status text not null,permission_basis text,estimated_cost_usd numeric not null default 0,idempotency_key text not null unique,result jsonb,error jsonb,retry_count int not null default 0,created_at timestamptz not null default now());
create table public.artifacts(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.owner_profiles on delete cascade,capture_id uuid references public.captures,action_id uuid references public.actions,title text not null,kind text not null,content text,storage_path text,idempotency_key text not null unique,created_at timestamptz not null default now());
create table public.jobs(id uuid primary key default gen_random_uuid(),capture_id uuid references public.captures on delete cascade,kind text not null,status text not null default 'queued',attempt int not null default 0,max_attempts int not null default 5,run_after timestamptz not null default now(),lease_owner text,lease_expires_at timestamptz,last_error jsonb,idempotency_key text not null unique,created_at timestamptz not null default now());
create table public.workflow_steps(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs on delete cascade,stage text not null,status text not null,input jsonb,output jsonb,prompt_version text,model_config jsonb,started_at timestamptz,finished_at timestamptz,unique(job_id,stage));
create table public.approvals(id uuid primary key default gen_random_uuid(),action_id uuid not null references public.actions on delete cascade,status text not null default 'pending',input_fingerprint text not null,decided_at timestamptz,created_at timestamptz not null default now());
create table public.research_runs(id uuid primary key default gen_random_uuid(),capture_id uuid references public.captures,query text not null,status text not null,conclusion jsonb,created_at timestamptz not null default now());
create table public.claims(id uuid primary key default gen_random_uuid(),research_run_id uuid references public.research_runs on delete cascade,capture_id uuid references public.captures,claim text not null,claim_type text not null,evidence_status text not null,source_excerpt text,provenance jsonb not null default '{}');
create table public.research_sources(id uuid primary key default gen_random_uuid(),research_run_id uuid not null references public.research_runs on delete cascade,url text not null,title text,published_at timestamptz,stance text,accessed_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,owner_id uuid,actor text not null,event text not null,subject_type text,subject_id uuid,detail jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.owner_profiles enable row level security;alter table public.goals enable row level security;alter table public.projects enable row level security;alter table public.captures enable row level security;alter table public.knowledge_items enable row level security;alter table public.actions enable row level security;alter table public.artifacts enable row level security;
create policy owner_profile on public.owner_profiles using(auth.uid()=id);create policy owner_goals on public.goals using(auth.uid()=owner_id);create policy owner_projects on public.projects using(auth.uid()=owner_id);create policy owner_captures on public.captures using(auth.uid()=owner_id);create policy owner_knowledge on public.knowledge_items using(auth.uid()=owner_id);create policy owner_actions on public.actions using(auth.uid()=owner_id);create policy owner_artifacts on public.artifacts using(auth.uid()=owner_id);
create or replace function public.ingest_instagram_event(p_event_id text,p_message_id text,p_sender_id text,p_disposition text,p_payload jsonb,p_normalized jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid;cid uuid;begin insert into raw_events(provider,event_id,message_id,sender_id,disposition,payload) values('instagram',p_event_id,p_message_id,p_sender_id,p_disposition,p_payload) on conflict(event_id) do update set event_id=excluded.event_id returning id into rid;if p_disposition='accepted' and not exists(select 1 from captures where raw_event_id=rid) then insert into captures(owner_id,raw_event_id,source_kind,owner_note,state) values((select id from owner_profiles limit 1),rid,'instagram_dm',p_normalized->>'text','received') returning id into cid;insert into jobs(capture_id,kind,idempotency_key) values(cid,'process_capture','capture:'||cid);end if;return rid;end$$;
create or replace function public.claim_jobs(p_worker text,p_limit int default 3,p_lease_seconds int default 120) returns setof public.jobs language plpgsql security definer set search_path=public as $$begin return query update jobs set status='executing',lease_owner=p_worker,lease_expires_at=now()+make_interval(secs=>p_lease_seconds) where id in(select id from jobs where (status in('queued','retrying') and run_after<=now()) or (status='executing' and lease_expires_at<now()) order by run_after for update skip locked limit p_limit) returning *;end$$;
